package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os/exec"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trail"

	"charm.land/huh/v2"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/spf13/cobra"
)

const (
	defaultTrailListLimit  = 10
	defaultTrailListAuthor = ""
	trailListAuthorMe      = "me"
	defaultTrailListStatus = string(trail.StatusInProgress)
	trailAuthorColumnWidth = 15
)

func newTrailCmd() *cobra.Command {
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:    "trail",
		Short:  "Manage trails for your branches",
		Hidden: true,
		Long: `Trails are branch-centric work tracking abstractions. They describe the
"why" and "what" of your work, while checkpoints capture the "how" and "when".

Running 'entire trail' without a subcommand shows the trail for the current
branch, or lists recent trails if no trail exists for the current branch.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailShow(cmd.Context(), cmd.OutOrStdout(), insecureHTTPAuth)
		},
	}

	cmd.PersistentFlags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
		"Allow API calls over plain HTTP (insecure, for local development only)")
	if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
	}

	cmd.AddCommand(newTrailListCmd())
	cmd.AddCommand(newTrailCreateCmd())
	cmd.AddCommand(newTrailUpdateCmd())
	cmd.AddCommand(newTrailWatchCmd())

	return cmd
}

// trailInsecureHTTP reads the persistent --insecure-http-auth flag from the trail root command.
func trailInsecureHTTP(cmd *cobra.Command) bool {
	v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
	return v
}

// runTrailShow shows the trail for the current branch, or falls through to list.
func runTrailShow(ctx context.Context, w io.Writer, insecureHTTP bool) error {
	branch, err := GetCurrentBranch(ctx)
	if err != nil {
		return runTrailListAll(ctx, w, defaultTrailListAuthor, defaultTrailListStatus, false, defaultTrailListLimit, insecureHTTP)
	}

	client, err := NewAuthenticatedAPIClient(insecureHTTP)
	if err != nil {
		return fmt.Errorf("authentication required: %w", err)
	}

	host, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil {
		return fmt.Errorf("failed to resolve repository: %w", err)
	}

	found, err := findTrailByBranch(ctx, client, host, owner, repo, branch)
	if err != nil {
		return err
	}
	if found == nil {
		return runTrailListAll(ctx, w, defaultTrailListAuthor, defaultTrailListStatus, false, defaultTrailListLimit, insecureHTTP)
	}

	printTrailDetails(w, found.ToMetadata())
	return nil
}

func printTrailDetails(w io.Writer, m *trail.Metadata) {

// Package trail provides types and helpers for managing trail metadata.
// Trails are branch-centric work tracking abstractions stored on the
// entire/trails/v1 orphan branch. They answer "why/what" (human intent)
// while checkpoints answer "how/when" (machine snapshots).
package trail

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"regexp"
	"strings"
	"time"
)

const idLength = 6 // 6 bytes = 12 hex chars

// ID is a 12-character hex identifier for trails.
type ID string

// EmptyID represents an unset or invalid trail ID.
const EmptyID ID = ""

// idRegex validates the format: exactly 12 lowercase hex characters.
var idRegex = regexp.MustCompile(`^[0-9a-f]{12}$`)

// GenerateID creates a new random 12-character hex trail ID.
func GenerateID() (ID, error) {
	bytes := make([]byte, idLength)
	if _, err := rand.Read(bytes); err != nil {
		return EmptyID, fmt.Errorf("failed to generate random trail ID: %w", err)
	}
	return ID(hex.EncodeToString(bytes)), nil
}

// ValidateID checks if a string is a valid trail ID format.
func ValidateID(s string) error {
	if !idRegex.MatchString(s) {
		return fmt.Errorf("invalid trail ID %q: must be 12 lowercase hex characters", s)
	}
	return nil
}

// String returns the trail ID as a string.
func (id ID) String() string {
	return string(id)
}

// IsEmpty returns true if the trail ID is empty or unset.
func (id ID) IsEmpty() bool {
	return id == EmptyID
}

// Path returns the sharded storage path for this trail ID.
// Uses first 2 characters as shard (256 buckets), remaining as folder name.
// Example: "a3b2c4d5e6f7" -> "a3/b2c4d5e6f7"
func (id ID) Path() string {
	if len(id) < 3 {
		return string(id)
	}
	return string(id[:2]) + "/" + string(id[2:])
}

// ShardParts returns the shard prefix and suffix separately.
// Example: "a3b2c4d5e6f7" -> ("a3", "b2c4d5e6f7")
func (id ID) ShardParts() (shard, suffix string) {
	if len(id) < 3 {
		return string(id), ""
	}
	return string(id[:2]), string(id[2:])
}

