authApiRoutes.get("/me", async (c) => {
  const meStart = Date.now()
  // requireAuth middleware already ran — capture how long it took via the timestamp it set
  const authTimestamp = c.get("authTimestamp")
  const middlewareMs = authTimestamp !== undefined ? meStart - authTimestamp : undefined
  const userId = c.get("userId")
  const localDev = isLocalDev(c.env)

  const db = getDb(c.env)

  const t0 = Date.now()
  const user = await db.users.findById(userId)
  const userFetchMs = Date.now() - t0

  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  const currentIsAdmin = isAdmin(c.env, user.is_admin)

  const [
    { value: hasPersonal, ms: hasPersonalMs },
    { value: isEntireHqMember, ms: orgMembershipDbMs },
    { value: repoPreferences, ms: repoPreferencesMs },
  ] = await Promise.all([
    timed(async () =>
      user.github_login ? db.installations.userHasPersonal(userId, user.github_login) : false,
    ),
    timed(async () => {
      if (localDev || !user.github_login) {
        return localDev
      }

      const membership = await db.orgMemberships.findByUserAndOrgLogin(userId, "entirehq")
      return !!(membership && membership.role)
    }),
    timed(() => getRepoPreferencesResponse(db, userId)),
  ])

  // Sync org membership via GitHub API in the background to keep the DB fresh.
  if (!localDev && user.github_login) {
    await runInBackground(c, async () => {
      try {
        const membership = await checkEntireOrgMembership(db, c.env, userId, user.github_login!)
        // Auto-revoke admin only when GitHub API definitively confirmed non-membership.
        if (currentIsAdmin && !membership.isMember && !membership.fromCache) {
          await db.users.setAdmin(userId, false)
          await c.env.ENTIRE_CACHE.delete(`user:${userId}`)
        }
      } catch (err) {
        console.error("Failed to check entirehq org membership:", err)
        recordSpanError(err)
      }
    })
  }

