149	func runTrailListAll(ctx context.Context, w io.Writer, authorFilter, statusFilter string, jsonOutput bool, limit int, insecureHTTP bool) error {
150		if limit <= 0 {
151			return errors.New("limit must be greater than 0")
152		}
153		statusFilters, err := parseTrailStatusFilter(statusFilter)
154		if err != nil {
155			return err
156		}
157		client, err := NewAuthenticatedAPIClient(insecureHTTP)
158		if err != nil {
159			return fmt.Errorf("authentication required: %w", err)
160		}
161	
162		host, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
163		if err != nil {
164			return fmt.Errorf("failed to resolve repository: %w", err)
165		}
166	
167		resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
168		if err != nil {
169			return fmt.Errorf("failed to list trails: %w", err)
170		}
171		defer resp.Body.Close()
172		if err := checkTrailResponse(resp); err != nil {
173			return err
174		}
175	
176		var listResp api.TrailListResponse
177		if err := api.DecodeJSON(resp, &listResp); err != nil {
178			return fmt.Errorf("failed to decode trail list: %w", err)
179		}
180	
181		// Convert to metadata for display
182		trails := make([]*trail.Metadata, 0, len(listResp.Trails))
183		for i := range listResp.Trails {
184			trails = append(trails, listResp.Trails[i].ToMetadata())
185		}
186	
187		currentUserLogin := ""
188		if authorFilter == trailListAuthorMe {
189			login, err := fetchCurrentUserLogin(ctx, client)
190			if err != nil {
191				return err
192			}
193			currentUserLogin = login
194			authorFilter = login
195		}
196	
197		if authorFilter != "" {
198			trails = filterTrailsByAuthor(trails, authorFilter)
199		}
200	
201		if len(statusFilters) > 0 {
202			trails = filterTrailsByStatuses(trails, statusFilters)
203		}
204	
205		// Sort by updated_at descending, then keep only the most recent rows.
206		sort.Slice(trails, func(i, j int) bool {
207			return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
208		})
209		trails = limitTrails(trails, limit)
210	
211		if jsonOutput {
212			enc := json.NewEncoder(w)
213			enc.SetIndent("", "  ")
214			if err := enc.Encode(trails); err != nil {
215				return fmt.Errorf("failed to encode JSON: %w", err)
216			}
217			return nil
218		}
219	
220		if len(trails) == 0 {
221			fmt.Fprintln(w, "No trails found.")
222			fmt.Fprintln(w)
223			fmt.Fprintln(w, "Commands:")
224			fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
225			fmt.Fprintln(w, "  entire trail list     List recent trails")
