// ---- Router ----

export const trailRoutes = new Hono<{ Bindings: Env; Variables: Variables }>()

trailRoutes.use("*", requireBearerAuth)
trailRoutes.use("*", requireAdmin)

// GET /:host/:owner/:repo — List trails
trailRoutes.get(
  "/:host/:owner/:repo",
  describeRoute({
    tags: ["Trails"],
    summary: "List trails for a repository",
    responses: {
      200: {
        description: "Trail list",
        content: {
          "application/json": {
            schema: resolver(
              z.object({
                trails: z.array(trailInfoSchema),
                repo_full_name: z.string(),
                default_branch: z.string(),
                updated_at: z.string(),
              }),
            ),
          },
        },
      },
      401: {
        description: "Not authenticated",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      403: {
        description: "Forbidden",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      404: {
        description: "Repository not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveGitHubContext(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, githubToken } = ctx

    try {
      const { trails: trailRows } = await db.trails.listByRepo(repoAccess.id)

      const pairs = trailRows
        .filter((r): r is typeof r & { branch: string } => r.branch !== null)
        .map((r) => ({ branch: r.branch, base: resolveBaseBranch(r, repoAccess) }))
      let checkpointCounts = new Map<string, number>()
      try {
        checkpointCounts = await db.checkpoints.countForBranchesExcludingBase(repoAccess.id, pairs)
      } catch {
        // Ignore
      }

      const trails: TrailInfo[] = []
      for (const row of trailRows) {
        const checkpointCount = row.branch ? (checkpointCounts.get(row.branch) ?? 0) : 0

        trails.push({
          number: row.number,
          branch: row.branch ?? row.original_branch,
          base: row.base,
          title: row.title,
          body: row.body ?? "",
          status: row.status,
          author: row.author,
          assignees: row.assignees,
          labels: row.labels,
          created_at: row.created_at,
          updated_at: row.updated_at,
          merged_at: row.merged_at,
          priority: (row.priority ?? "none") as TrailPriority,
          type: (row.type as TrailType) ?? null,
          reviewers: Array.isArray(row.reviewers)
            ? (row.reviewers as unknown as TrailReviewer[])
            : [],
          comment_count: row.comment_count,
          unresolved_count: row.unresolved_count,
          checkpoint_count: checkpointCount,
        })
      }

      let hasWritePermission = false
      if (repoAccess.installation_id) {
        const gid = await db.installations.getGithubId(repoAccess.installation_id)
        if (gid) {
          hasWritePermission = await checkInstallationWritePermission(
            gid,
            { appId: c.env.GITHUB_CLIENT_ID, privateKey: c.env.GITHUB_APP_PRIVATE_KEY },
            c.env.ENTIRE_CACHE,
          )
        }
      }

      return c.json({
        trails,
        repo_full_name: repoFullName,
        default_branch: repoAccess.default_branch ?? "main",
        updated_at: new Date().toISOString(),
        has_write_permission: hasWritePermission,
      })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to fetch trails for ${repoFullName}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to fetch trails" }, 500)
    }
  },

