func trailListStatusOrder(filter []trail.Status) []trail.Status {
	order := []trail.Status{
		trail.StatusInProgress,
		trail.StatusOpen,
		trail.StatusInReview,
		trail.StatusDraft,
		trail.StatusMerged,
		trail.StatusClosed,
	}
	if len(filter) == 0 {
		return order
	}

